from collections import defaultdict
from datetime import datetime

csv_path = '/home/agent/workspace/bookstore_orders.csv'
output_path = '/home/agent/workspace/carrier-otd.csv'

stats = defaultdict(lambda: {'total_delivered':0, 'on_time':0})

def parse_date(s):
    # estimated is YYYY-MM-DD, actual is YYYY-MM-DD HH:MM:SS
    try:
        return datetime.strptime(s[:10], '%Y-%m-%d').date()
    except:
        return None

with open(csv_path, newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['fulfillment_status'].strip() != 'Delivered':
            continue
        carrier = row['carrier_name'].strip()
        if not carrier:
            continue
        est_str = row['estimated_delivery_date'].strip()
        act_str = row['actual_delivery_date'].strip()
        if not est_str or not act_str:
            continue
        # parse dates
        try:
            est = datetime.strptime(est_str, '%Y-%m-%d').date()
            act = datetime.strptime(act_str[:10], '%Y-%m-%d').date()
        except Exception:
            # fallback
            try:
                est = datetime.strptime(est_str[:10], '%Y-%m-%d').date()
                act = datetime.strptime(act_str[:10], '%Y-%m-%d').date()
            except:
                continue
        stats[carrier]['total_delivered'] += 1
        if act <= est:
            stats[carrier]['on_time'] += 1

results = []
for carrier, data in stats.items():
    total = data['total_delivered']
    on_time = data['on_time']
    pct = (on_time/total*100) if total else 0
    results.append({
        'CarrierName': carrier,
        'TotalDelivered': total,
        'OnTimeDelivered': on_time,
        'OnTimePct': round(pct, 2)
    })

results.sort(key=lambda x: x['OnTimePct'], reverse=True)

with open(output_path, 'w', newline='', encoding='utf-8') as out_f:
    writer = csv.writer(out_f)
    writer.writerow(['CarrierName','TotalDelivered','OnTimeDelivered','OnTimePct'])
    for r in results:
        writer.writerow([r['CarrierName'], r['TotalDelivered'], r['OnTimeDelivered'], f"{r['OnTimePct']:.2f}"])

print(f"Wrote {len(results)} carriers to {output_path}")
for r in results:
    print(r)
"}

