from collections import defaultdict
from datetime import datetime

csv_path = '/home/agent/workspace/bookstore_orders.csv'
output_path = '/home/agent/workspace/carrier-delivery-time.csv'

stats = defaultdict(lambda: {'count': 0, 'total_hours': 0.0})

def parse_dt(s):
    try:
        return datetime.strptime(s, '%Y-%m-%d %H:%M:%S')
    except:
        try:
            return datetime.strptime(s, '%Y-%m-%d %H:%M:%S')
        except:
            return None

with open(csv_path, newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['fulfillment_status'].strip() != 'Delivered':
            continue
        carrier = row['carrier_name'].strip()
        if not carrier:
            continue
        order_ts = row['order_timestamp'].strip()
        actual = row['actual_delivery_date'].strip()
        if not order_ts or not actual:
            continue
        try:
            t_order = datetime.strptime(order_ts, '%Y-%m-%d %H:%M:%S')
            t_actual = datetime.strptime(actual, '%Y-%m-%d %H:%M:%S')
        except:
            # fallback to date only
            try:
                t_order = datetime.strptime(order_ts, '%Y-%m-%d %H:%M:%S')
                t_actual = datetime.strptime(actual, '%Y-%m-%d %H:%M:%S')
            except:
                continue
        delta_hours = (t_actual - t_order).total_seconds() / 3600.0
        if delta_hours < 0:
            # shouldn't happen, but skip negative
            continue
        stats[carrier]['count'] += 1
        stats[carrier]['total_hours'] += delta_hours

results = []
for carrier, data in stats.items():
    count = data['count']
    avg = data['total_hours'] / count if count else 0
    results.append({
        'CarrierName': carrier,
        'DeliveredOrders': count,
        'AvgDeliveryHours': round(avg, 2)
    })

results.sort(key=lambda x: x['AvgDeliveryHours'])

with open(output_path, 'w', newline='', encoding='utf-8') as out_f:
    writer = csv.writer(out_f)
    writer.writerow(['CarrierName','DeliveredOrders','AvgDeliveryHours'])
    for r in results:
        writer.writerow([r['CarrierName'], r['DeliveredOrders'], f"{r['AvgDeliveryHours']:.2f}"])

print(f"Wrote {len(results)} carriers to {output_path}")
for r in results:
    print(r)
